"""Writes tools/stats/cases_t4.txt: nearest-neighbour searches, crosstab, polyconf, nearcorr, one-hot coding."""
import os
here = os.path.dirname(os.path.abspath(__file__))
PRE = "X=[x(1:20)' y(1:20)']; Y=[x(21:25)' y(21:25)']; X3=[X x(31:50)']; G1=[1 2 1 3 3 2 1 2 3 3]'; G2=[1 2 2 3 3 1 1 2 3 2]'; "
L = ["# generated by make_t4_cases.py"]
def add(cs, fmt="r = {c};"):
    for c in cs: L.append(fmt.format(c=c))
two = "[a_,b_] = {c}; r = {{a_,b_}};"
cellr = "[a_,b_] = {c}; r = {{cellfun(@numel,a_), [a_{{:}}], [b_{{:}}]}};"
add(["knnsearch(X,Y)", "knnsearch(X,Y,'K',3)", "knnsearch(X,Y,'K',3,'Distance','cityblock')", "knnsearch(X,Y,'K',2,'Distance','chebychev')", "knnsearch(X,Y,'K',2,'Distance','minkowski','P',3)", "knnsearch(X,Y,'K',2,'Distance','cosine')", "knnsearch(X,Y,'K',2,'Distance','correlation')",
     "knnsearch(X,Y,'K',2,'Distance','seuclidean')", "knnsearch(X,Y,'K',2,'Distance','seuclidean','Scale',[1 2])", "knnsearch(X,Y,'K',2,'Distance','mahalanobis')", "knnsearch(X,Y,'K',2,'Distance','mahalanobis','Cov',[2 0.3;0.3 1])", "knnsearch(X,Y,'K',2,'Distance','spearman')",
     "knnsearch(X,Y,'K',2,'Distance','hamming')", "knnsearch(X,Y,'K',2,'Distance','jaccard')", "knnsearch(X,Y,'K',2,'Distance',@(a,b) sum(abs(a-b),2))", "knnsearch(X,Y,'K',2,'Distance','euclidean','NSMethod','exhaustive')", "knnsearch(X,Y,'K',2,'NSMethod','kdtree')",
     "knnsearch(X,Y,'K',25)", "knnsearch(X,Y,'K',0)", "knnsearch(X,Y,'K',1.5)", "knnsearch(X,Y(:,1))", "knnsearch([1 1;1 2;2 2;2 1;3 3],[1.5 1.5],'K',2)", "knnsearch(X,Y,'SortIndices',false,'K',3)",
     "knnsearch(X,[Y;NaN NaN])", "knnsearch([X;NaN 1],Y)", "knnsearch(X,Y,'Foo',1)", "knnsearch(X,Y,'K',2,'BucketSize',5)", "knnsearch(X,Y,'K',2,'Distance','foo')", "knnsearch(single(X),single(Y),'K',2)", "knnsearch(X,Y,'K',2,'Distance','cityblock','NSMethod','kdtree')", "knnsearch(X3,X3(1:3,:),'K',4)", "knnsearch(X,X,'K',2)", "knnsearch(X)", "knnsearch(X,Y,'K',3,'IncludeTies',false)"], two)
add(["knnsearch(X,Y,'IncludeTies',true)", "knnsearch([1 1;1 2;2 2;2 1;3 3],[1.5 1.5],'K',2,'IncludeTies',true)", "knnsearch([1 1;1 2;2 2;2 1;3 3],[1.5 1.5;1 1],'K',3,'IncludeTies',true)"], cellr)
add(["rangesearch(X,Y,0.5)", "rangesearch(X,Y,1)", "rangesearch(X,Y,1,'Distance','cityblock')", "rangesearch(X,Y,1,'Distance','chebychev')", "rangesearch(X,Y,1,'Distance','minkowski','P',3)", "rangesearch(X,Y,0.2,'Distance','cosine')", "rangesearch(X,Y,1,'SortIndices',false)", "rangesearch(X,Y,0)", "rangesearch(X,Y,-1)", "rangesearch(X,Y)", "rangesearch(X,Y,1,'NSMethod','kdtree')", "rangesearch(X,Y(:,1),1)", "rangesearch(X,[Y;NaN NaN],1)", "rangesearch(X,Y,1,'Foo',1)", "rangesearch(single(X),single(Y),1)", "rangesearch(X,Y,1,'Distance',@(a,b) sqrt(sum((a-b).^2,2)))", "rangesearch(X,Y,100)", "rangesearch(X,Y,[1 2])"], cellr)
add(["crosstab(G1,G2)", "crosstab(G1)", "crosstab(G1,G2,G1)", "crosstab({'a','b','a','c'}',[1 2 1 2]')", "crosstab([1 NaN 2 1]',[1 2 2 1]')", "crosstab(G1,G2(1:5))", "crosstab()", "crosstab(A)", "crosstab(G1>1,G2>1)", "crosstab([3 1 2 3]',[1 1 2 2]')", "crosstab({'x','y','x'}',{'u','u','v'}')"], "[a_,b_,c_,d_] = {c}; r = {{a_,b_,c_,d_{{:}}}};")
for deg, extra in [(1,""), (2,""), (1,",'alpha',0.1"), (1,",'predopt','observation'"), (1,",'simopt','on'"), (1,",'simopt','on','predopt','observation'"), (1,",'foo',1"), (1,",'alpha',2"), (3,",'alpha',0.01")]:
    L.append(f"[p_,S_] = polyfit(x(1:12),y(1:12),{deg}); [Y_,D_] = polyconf(p_,x(13:16),S_{extra}); r = {{Y_,D_}};")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); r = polyconf(p_,x(13:16));")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); [Y_,D_] = polyconf(p_,x(13:16)'',S_); r = {Y_,D_};")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); [Y_,D_] = polyconf(p_,[x(13:14);x(15:16)],S_); r = {Y_,D_};")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); [Y_,D_] = polyconf(p_,x(13:16),S_,'alpha',0.2,'predopt','curve'); r = {Y_,D_};")
L.append("[p_,S_,mu_] = polyfit(x(1:12),y(1:12),2); [Y_,D_] = polyconf(p_,x(13:16),S_,'mu',mu_); r = {Y_,D_};")
L.append("[p_,S_,mu_] = polyfit(x(1:12),y(1:12),2); [Y_,D_] = polyconf(p_,x(13:16),S_,0.1,mu_); r = {Y_,D_};")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); [Y_,D_] = polyconf(p_,x(13:16),S_,0.1); r = {Y_,D_};")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); [Y_,D_] = polyconf(p_,x(13:16),S_,'predopt','x'); r = {Y_,D_};")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); [Y_,D_] = polyconf(p_,x(13:16),S_,'simopt','x'); r = {Y_,D_};")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); [Y_,D_] = polyconf(p_,x(13:16)); r = {Y_,D_};")
L.append("r = polyconf();")
L.append("[p_,S_] = polyfit(x(1:12),y(1:12),1); [Y_,D_] = polyconf(p_,x(13:16),single(S_.R)); r = {Y_,D_};")
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_t4.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
